package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** A report uses the stated measurement resolution, never an arbitrary preferred precision. */
public final class ContextAccuracy {
 private ContextAccuracy(){}
 public static final String ID="contextAccuracyChoice";
 public static final List<Catalog.Skill> SKILLS=List.of(new Catalog.Skill(ID,"측정 단위에 맞게 나타내기",6,1,1,"",ID,100,"el_decimal_round","측정 기록의 단위에 맞춰 반올림한 값을 고른다."));
 static final List<Integer> AMOUNTS=new ArrayList<>();
 static {for(int n=1;n<=99999;n++){BigDecimal v=BigDecimal.valueOf(n,3);if(v.setScale(1,RoundingMode.HALF_UP).compareTo(v.setScale(2,RoundingMode.HALF_UP))!=0&&v.setScale(2,RoundingMode.HALF_UP).compareTo(v)!=0)AMOUNTS.add(n);}}
 public record Givens(BigDecimal amount,int places,String unit){}
 public static boolean supports(String id){return ID.equals(id);}
 static int count(){return AMOUNTS.size()*6;}
 static Question at(int index){if(index<0||index>=count())throw new IllegalArgumentException("accuracy index");return make(AMOUNTS.get(index/6),index%3+1,index%6<3?"m":"L");}
 public static Question make(int milli,int places,String unit){if(milli<1||milli>99999||places<1||places>3||!Set.of("m","L").contains(unit))throw new IllegalArgumentException("accuracy domain");BigDecimal amount=BigDecimal.valueOf(milli,3);Set<String> options=new LinkedHashSet<>();for(int p=1;p<=3;p++)options.add(amount.setScale(p,RoundingMode.HALF_UP).toPlainString());if(amount.setScale(1,RoundingMode.HALF_UP).compareTo(amount.setScale(2,RoundingMode.HALF_UP))==0||amount.setScale(2,RoundingMode.HALF_UP).compareTo(amount)==0)throw new IllegalArgumentException("indistinguishable accuracy options");String resolution=BigDecimal.ONE.movePointLeft(places).toPlainString();String prompt=(unit.equals("m")?"계산한 끈 길이: ":"계산한 물의 양: ")+amount+" "+unit+"\n기록 단위: "+resolution+" "+unit+"\n기록 단위에 맞게 반올림한 값을 고르세요.";Question q=new Question(ID,prompt,"",amount.setScale(places,RoundingMode.HALF_UP).toPlainString());q.kind="contextAccuracy";q.choices=new ArrayList<>(options);Collections.rotate(q.choices,(milli+places)%3);q.choiceLabels=new LinkedHashMap<>();for(String value:q.choices)q.choiceLabels.put(value,value+" "+unit);q.stepSupport=false;attach(q);return q;}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(계산한 끈 길이|계산한 물의 양): (\\d{1,2}\\.\\d{3}) (m|L)\\n기록 단위: (0\\.1|0\\.01|0\\.001) \\3\\n기록 단위에 맞게 반올림한 값을 고르세요\\.").matcher(q.prompt);if(!m.matches()||!m.group(1).equals(m.group(3).equals("m")?"계산한 끈 길이":"계산한 물의 양"))return null;BigDecimal amount=new BigDecimal(m.group(2));if(amount.signum()<=0||amount.compareTo(new BigDecimal("99.999"))>0)return null;return new Givens(amount,new BigDecimal(m.group(4)).scale(),m.group(3));}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){return IndexedQuestionSupply.choose(count(),ContextAccuracy::at,random,limits,recent);}
 static Checker.Result check(Question q,List<String> answers){Givens v=read(q);if(v==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"값 선택 필요");String raw=answers.get(0).trim();String expected=v.amount().setScale(v.places(),RoundingMode.HALF_UP).toPlainString();Set<String> valid=new HashSet<>();for(int p=1;p<=3;p++)valid.add(v.amount().setScale(p,RoundingMode.HALF_UP).toPlainString());if(!valid.contains(raw))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"값 선택 필요");boolean same=raw.equals(expected);return new Checker.Result(same?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,same?-1:0,same?"계산 확인 완료":"기록 단위 확인");}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="context-accuracy-v1";LinkedHashMap<String,String> options=new LinkedHashMap<>();for(int p=1;p<=3;p++)options.put(""+p,BigDecimal.ONE.movePointLeft(p).toPlainString()+" 단위까지");h.choice("기록 단위에 맞는 자리를 고르세요.",options,""+v.places());Question proxy=new Question("el_decimal_round",v.amount()+"을 소수 "+List.of("첫째","둘째","셋째").get(v.places()-1)+" 자리까지 반올림하면?","","poison");RoundingRelations.attach(proxy);for(var frame:proxy.studyGuide.frames)if(frame.options.isEmpty())frame.inputFormat="decimalValue";h.frames.addAll(proxy.studyGuide.frames);q.studyGuide=h;}
}
